const world = await World.create(container, {
  xr: false,
  render: {
    near: 0.001, far: 200,
    camera: { position: [0, 1.6, 0], lookAt: [0, 1.55, -1] },
  },
  input: { canvasPointerEvents: true },
  features: {
    grabbing: true,
    locomotion: { browserControls: true },  // WASD/arrows + Space + gamepad; app owns mouselook
    physics: true,
  },
});
```

### Dual-Runtime Pattern (XR + Browser Fallback)

For games that should work both in VR and in the browser:

```typescript
const world = await World.create(container, {
  xr: { offer: 'once' },
  input: { canvasPointerEvents: true },
  features: {
    grabbing: true,
    locomotion: { browserControls: true },
    physics: true,
  },
});
```

### Input System

```typescript
// InputManager facade (0.4.x)
world.input.xr              // XRInputManager (controllers, hands)
world.input.keyboard         // StatefulKeyboard
world.input.actions          // InputActionManager
world.input.browserGamepads  // Browser gamepad array

// Action-backed input (preferred for reusable intent-based systems)
world.input.actions.getAxis2D('locomotion.move');    // { x, y }
world.input.actions.getButtonDown('locomotion.jump');

// Built-in action names:
//   locomotion.move, locomotion.turn, locomotion.jump,
//   locomotion.teleportAim, locomotion.teleportCommit,
//   interaction.select
//
// Some names are reserved for app/user bindings and are not default-bound.

// Keyboard (browser-first)
world.input.keyboard.getKeyPressed('KeyW');   // held this frame
world.input.keyboard.getKeyDown('Space');     // pressed this frame
world.input.keyboard.getKeyUp('KeyE');        // released this frame
```

### ECS-Native Player Rig

```typescript
world.playerEntity           // Entity wrapping XROrigin Group
world.playerHeadEntity       // Entity for head space
world.playerSpaceEntities    // { head, raySpaces, gripSpaces, indexTipSpaces }

// Attach a HUD to the player's head
const hud = world.createTransformEntity(hudMesh, {
  parent: world.playerHeadEntity,
  persistent: true,
});
```

### Asset Management

```typescript
// getGLTF returns a fresh scene graph clone by default
// (geometries, materials, and animations remain shared)
const { scene } = AssetManager.getGLTF('myModel')!;
world.scene.add(scene);

// Opt into shared instance (old behavior)
const { scene } = AssetManager.getGLTF('myModel', { shared: true })!;
```

---

## 4b. Spatial UI (PanelUI) — MANDATORY for All Game UI

**CRITICAL: Do NOT use HTML DOM overlays (`<div>`, `<canvas>`, HTML elements) for
any game UI — menus, HUDs, scorecards, settings, overlays, etc. HTML overlays are
invisible in XR.** All UI must be built with IWSDK's spatial PanelUI system.

### Architecture

IWSDK's spatial UI is built on [`@pmndrs/uikit`](https://github.com/pmndrs/uikit)
and compiled via `@iwsdk/vite-plugin-uikitml`:

- **`.uikitml` files** — HTML-like markup compiled to JSON at build time
- **`PanelUI` component** — attaches compiled UI to an entity as a 3D panel
- **`ScreenSpace` component** — CSS-like positioning in browser; auto-returns to world-space in XR
- **`Follower` component** — head-locked panels that follow the player (HUDs)
- **`UIKitDocument`** — DOM-like API (`getElementById`, `querySelector`, etc.)

### Setup

Ensure `spatialUI: true` in world features (this is the default):

```typescript
const world = await World.create(container, {
  features: { spatialUI: true },
});
```

Install the uikitml vite plugin (included in generated apps):

```bash
npm install -D @iwsdk/vite-plugin-uikitml
```

Add to `vite.config.ts`:

```typescript
import { uikitml } from '@iwsdk/vite-plugin-uikitml';
// Add to plugins array alongside iwsdkDev
plugins: [uikitml(), iwsdkDev({ ai: { mode: 'agent' } })]
```

### Creating UI Panels

1. Write a `.uikitml` file in `ui/` directory:

```html
<!-- ui/hud.uikitml -->
<style>
  .hud-panel {
    display: flex;
    flex-direction: column;
    padding: 2;
    background-color: rgba(0, 0, 0, 0.8);
    border-color: #00ffff;
    border-width: 0.1;
    border-radius: 1;
  }
  .score-text {
    font-size: 3;
    color: #00ffff;
    font-weight: bold;
  }
  .label {
    font-size: 1.5;
    color: #a0a0a0;
  }
</style>
<div class="hud-panel">
  <span class="label">SCORE</span>
  <span id="score-value" class="score-text">0</span>
</div>
```

2. Attach to an entity with `PanelUI`:

```typescript
import { PanelUI, ScreenSpace, Follower, FollowBehavior, PanelDocument, UIKitDocument } from '@iwsdk/core';

// World-space panel (e.g., a menu board floating in the scene)
const menuEntity = world.createTransformEntity(undefined, { persistent: true });
menuEntity.object3D.position.set(0, 1.5, -2);
menuEntity.addComponent(PanelUI, {
  config: '/ui/menu.json',   // compiled from ui/menu.uikitml
  maxWidth: 0.8,
  maxHeight: 1.0,
});

// Head-following HUD (visible in XR, follows gaze)
const hudEntity = world.createTransformEntity(undefined, { persistent: true });
hudEntity.addComponent(PanelUI, {
  config: '/ui/hud.json',
  maxWidth: 0.3,
  maxHeight: 0.15,
});
hudEntity.addComponent(Follower, {
  target: world.player.head,
  offsetPosition: [0.25, -0.15, -0.5],
  behavior: FollowBehavior.PivotY,
  speed: 5,
  tolerance: 0.3,
});

// Screen-space panel (CSS positioning in browser, world-space in XR)
const overlayEntity = world.createTransformEntity(undefined, { persistent: true });
overlayEntity.addComponent(PanelUI, {
  config: '/ui/overlay.json',
  maxWidth: 0.4,
  maxHeight: 0.3,
});
overlayEntity.addComponent(ScreenSpace, {
  width: '40vw',
  height: 'auto',
  bottom: '24px',
  right: '24px',
  zOffset: 0.25,
});
```

### Updating UI at Runtime

Access UI elements via `PanelDocument` → `UIKitDocument`:

```typescript
// In a system's update():
const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
if (doc) {
  const scoreEl = doc.getElementById('score-value');
  if (scoreEl) {
    // UIKit components use signals for reactive updates
    scoreEl.text.value = `${currentScore}`;
  }
}
```

### UI Interaction with XR Controllers

PanelUI panels automatically receive pointer events from IWSDK's input system.
XR controller laser pointers can click buttons defined in `.uikitml`. Use
`cursor: pointer` in the style and standard event handling:

```html
<!-- ui/menu.uikitml -->
<button id="start-btn" class="menu-button" cursor="pointer">START GAME</button>
```

```typescript
const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument;
const startBtn = doc?.getElementById('start-btn');
startBtn?.addEventListener('click', () => { startGame(); });
```

### Key Rules

1. **Never use HTML DOM** for game UI — no `document.createElement`, no
   `innerHTML`, no `<div>` overlays, no HTML canvas HUD
2. **All menus, HUDs, scorecards, settings, notifications** must be `.uikitml` panels
3. **Use `Follower`** for head-locked HUDs in XR (score, health, ammo, etc.)
4. **Use `ScreenSpace`** for browser-mode overlays that auto-adapt in XR
5. **Use world-space `PanelUI`** for in-scene menus, leaderboards, settings boards
6. **Test all UI in XR** before expanding features — UI must be readable and
   interactive with controller laser pointer

---

## 5. Dev Server

```bash
npm run dev                    # Generated apps: dev up --open --foreground
npx iwsdk dev up               # Start dev:runtime through the CLI, usually backgrounded
npx iwsdk dev up --foreground  # Stay attached to terminal
npx iwsdk dev down           # Stop
npx iwsdk dev restart        # Restart
npx iwsdk dev status         # Check running state
npx iwsdk dev logs           # View recorded background server logs
npx iwsdk dev open           # Open in browser
```

Generated apps use `iwsdkDev({ ai: { mode: 'agent' } })`, which launches a
managed headless Playwright Chromium, registers the MCP WebSocket endpoint, and
records runtime state. Use `npx iwsdk dev status` for the resolved `localUrl`;
the generated starter template defaults to `https://localhost:8081/`, but
examples or existing apps may use another Vite port.

### Node.js Requirement

IWSDK 0.4.x requires Node.js satisfying:
`>=20.19.0 <21.0.0-0 || >=22.12.0 <23.0.0-0 || >=24.0.0`.
If your environment ships an unsupported default (for example Node 18), install
a supported Node version with your environment's version manager or platform
package and prepend it to `PATH`.

```bash
node --version
```

---

## 6. Adapter Management

Project creation syncs MCP adapter configs after dependency installation for the
selected AI tools. Sync or manage them explicitly with:

```bash
npx iwsdk adapter sync      # Write configs for all supported or selected AI tools
npx iwsdk adapter status     # Check adapter state
npx iwsdk adapter prune      # Remove IWSDK-managed MCP entries
```

Supported adapters: Claude Code, Cursor, OpenAI Codex, GitHub Copilot.

---

