// ─── State Manager ───────────────────────────────────────
export class GameStateManager {
  state: GameState = 'title';
  mode: GameMode = 'classic';
  difficulty: Difficulty = 'medium';
  machineIndex: number = 0;
  themeIndex: number = 0;

  // Game session
